SET
  @ID_592dda735e54 = '46F56956-008A-4ED3-B880-6A88AD9941E4' EXEC [${flyway:defaultSchema}].spUpdateAIModel @Description = @Description_592dda735e54,
  @ID = @ID_592dda735e54;

