@DriverClass_a71ea3d3287d NVARCHAR(255),
@Icon_a71ea3d3287d NVARCHAR(255),
@ContentCategory_a71ea3d3287d NVARCHAR(10),
@ToolLibraryClass_a71ea3d3287d NVARCHAR(100),
@Priority_a71ea3d3287d INT,
@DefaultDeliveryMode_a71ea3d3287d NVARCHAR(20),
@SystemSupplied_a71ea3d3287d BIT
SET
  @ID_a71ea3d3287d = '2E23F219-E790-4A77-9C86-CB19C711B71E'
SET
  @Name_a71ea3d3287d = N'Video Production'
SET
  @Description_a71ea3d3287d = N'Production specification, storyboard, style guide, data snapshot, review record, and rendered deliverables manifest for a Video Studio production (VideoGenerationSpec).'
SET
  @ContentType_a71ea3d3287d = N'application/vnd.mj.video-production+json'
SET
  @IsEnabled_a71ea3d3287d = 1
SET
  @ParentID_a71ea3d3287d = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[ArtifactType]
    WHERE
      LOWER([Name]) = LOWER(N'JSON')
  )
SET
  @ExtractRules_a71ea3d3287d = N'[{"name":"name","description":"Extracts the video production title from Film.OneSentence (truncated to 100 chars), falling back to Archetype.Name or ''Video Production''","type":"string","standardProperty":"name","extractor":"try {\n  const spec = JSON.parse(content);\n  const oneSentence = spec && spec.Film && typeof spec.Film.OneSentence === ''string''\n    ? spec.Film.OneSentence.trim()\n    : '''';\n  if (oneSentence.length > 0) {\n    return oneSentence.slice(0, 100);\n  }\n  const archetypeName = spec && spec.Archetype && typeof spec.Archetype.Name === ''string''\n    ? spec.Archetype.Name.trim()\n    : '''';\n  if (archetypeName.length > 0) {\n    return archetypeName;\n  }\n  return ''Video Production'';\n} catch (_e) {\n  return ''Video Production'';\n}\n"},{"name":"description","description":"Extracts the production purpose from Film.Purpose","type":"string","standardProperty":"description","extractor":"try {\n  const spec = JSON.parse(content);\n  const purpose = spec && spec.Film && typeof spec.Film.Purpose === ''string''\n    ? spec.Film.Purpose.trim()\n    : '''';\n  return purpose.length > 0 ? purpose : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"archetype","description":"Extracts the video archetype name from Archetype.Name","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const archetypeName = spec && spec.Archetype && typeof spec.Archetype.Name === ''string''\n    ? spec.Archetype.Name.trim()\n    : '''';\n  return archetypeName.length > 0 ? archetypeName : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"durationSeconds","description":"Extracts the target runtime in seconds from Film.DurationSeconds","type":"number","extractor":"try {\n  const spec = JSON.parse(content);\n  const duration = spec && spec.Film ? spec.Film.DurationSeconds : undefined;\n  return typeof duration === ''number'' && Number.isFinite(duration) ? duration : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"formats","description":"Extracts the target aspect ratio formats from Film.Formats","type":"Array<string>","extractor":"try {\n  const spec = JSON.parse(content);\n  const formats = spec && spec.Film && Array.isArray(spec.Film.Formats)\n    ? spec.Film.Formats.filter(function (f) { return typeof f === ''string'' && f.trim().length > 0; })\n    : [];\n  return formats;\n} catch (_e) {\n  return [];\n}\n"},{"name":"asOf","description":"Extracts the frozen data snapshot timestamp from DataSnapshot.AsOf","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const asOf = spec && spec.DataSnapshot && typeof spec.DataSnapshot.AsOf === ''string''\n    ? spec.DataSnapshot.AsOf.trim()\n    : '''';\n  return asOf.length > 0 ? asOf : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"displayMarkdown","description":"Builds a markdown summary of the VideoGenerationSpec including one-sentence heading, archetype, duration, formats, status, data as-of timestamp, and generated asset count","type":"string","standardProperty":"displayMarkdown","extractor":"try {\n  const spec = JSON.parse(content);\n  if (!spec || typeof spec !== ''object'') {\n    return null;\n  }\n\n  const oneSentence = spec.Film && typeof spec.Film.OneSentence === ''string'' && spec.Film.OneSentence.trim().length > 0\n    ? spec.Film.OneSentence.trim()\n    : ''Video Production'';\n  const archetype = spec.Archetype && typeof spec.Archetype.Name === ''string'' && spec.Archetype.Name.trim().length > 0\n    ? spec.Archetype.Name.trim()\n    : ''Unspecified'';\n  const duration = spec.Film && typeof spec.Film.DurationSeconds === ''number'' && Number.isFinite(spec.Film.DurationSeconds)\n    ? spec.Film.DurationSeconds + ''s''\n    : ''Unspecified'';\n  const formats = spec.Film && Array.isArray(spec.Film.Formats) && spec.Film.Formats.length > 0\n    ? spec.Film.Formats.join('', '')\n    : ''Unspecified'';\n  const status = typeof spec.Status === ''string'' && spec.Status.trim().length > 0\n    ? spec.Status.trim()\n    : ''Unspecified'';\n\n  const lines = [\n    ''# '' + oneSentence,\n    '''',\n    ''- **Archetype:** '' + archetype,\n    ''- **Duration:** '' + duration,\n    ''- **Formats:** '' + formats,\n    ''- **Status:** '' + status\n  ];\n\n  const asOf = spec.DataSnapshot && typeof spec.DataSnapshot.AsOf === ''string''\n    ? spec.DataSnapshot.AsOf.trim()\n    : '''';\n  if (asOf.length > 0) {\n    lines.push(''- Data as of '' + asOf);\n  }\n\n  const approved = spec.Assets && Array.isArray(spec.Assets.Approved)\n    ? spec.Assets.Approved\n    : [];\n  const generatedCount = approved.filter(function (asset) {\n    return asset && asset.Provenance === ''Generated'';\n  }).length;\n  if (generatedCount > 0) {\n    lines.push(''- Contains AI-generated assets: '' + generatedCount);\n  }\n\n  return lines.join(''\\n'');\n} catch (_e) {\n  return null;\n}\n"},{"name":"posterFileID","description":"Extracts the MJ: Files ID for the rendered poster frame from Output.PosterFileID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const posterFileId = spec && spec.Output && typeof spec.Output.PosterFileID === ''string''\n    ? spec.Output.PosterFileID.trim()\n    : '''';\n  return posterFileId.length > 0 && !posterFileId.startsWith(''inline:'') ? posterFileId : null;\n} catch (_e) {\n  return null;\n}\n\n"},{"name":"status","description":"Extracts the lifecycle status of the video production from Status","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const status = spec && typeof spec.Status === ''string''\n    ? spec.Status.trim()\n    : '''';\n  return status.length > 0 ? status : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"brandKitID","description":"Extracts the MJ: Brand Kits ID referenced by the video production from BrandKitID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const brandKitId = spec && typeof spec.BrandKitID === ''string''\n    ? spec.BrandKitID.trim()\n    : '''';\n  return brandKitId.length > 0 ? brandKitId : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"companyID","description":"Extracts the Company ID associated with the video production from CompanyID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const companyId = spec && typeof spec.CompanyID === ''string''\n    ? spec.CompanyID.trim()\n    : '''';\n  return companyId.length > 0 ? companyId : null;\n} catch (_e) {\n  return null;\n}\n"}]'
SET
