    artifactDirective?: { behavior: ''create-new'' | ''version-source'' | ''suppress''; targetArtifactId?: string; name?: string; description?: string };
{% endif %}
{% endif %}
{% if __agentTypePromptParams.includeResponseTypeDefinition.scratchpad != false %}
