-- Save MJ: Query SQLs (core SP call only)
DECLARE @ID_28b59a90308b UNIQUEIDENTIFIER,
@QueryID_28b59a90308b UNIQUEIDENTIFIER,
@SQLDialectID_28b59a90308b UNIQUEIDENTIFIER,
@SQL_28b59a90308b NVARCHAR(MAX)
SET
  @ID_28b59a90308b = '77C592A7-9010-4B99-A3ED-571199C05B8B'
SET
  @QueryID_28b59a90308b = '226484B9-8178-418A-8CDB-25D2BF234684'
SET
  @SQLDialectID_28b59a90308b = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_28b59a90308b = N'-- PostgreSQL variant: completed prompt runs that carry no cost, newest first. Live-only.
-- Mirrors ai-usage-unpriced-audit.sql. Differences:
--   * `[${flyway:defaultSchema}].vwAIUsageFacts` → `${flyway:defaultSchema}."vwAIUsageFacts"`; column references double-quoted, since PG folds
--     unquoted names to lower case.
--   * `SELECT TOP (n)` → `LIMIT n`.
SELECT
    "PromptRunID",
    "AgentRunID",
    "ParentPromptRunID",
    "RunAt",
    "RunAtUTC",
    "PromptID",
    "ModelID",
    "VendorID",
    "AgentID",
    "ConfigurationID",
    "UserID",
    "ConversationID",
    "PrimaryScopeEntityID",
    "PrimaryScopeRecordID",
    "RunType",
    "SourceKind",
    "Status",
    "Success",
    "TokensPrompt",
    "TokensCompletion",
    "TokensCacheRead",
    "TokensCacheWrite",
    "InputUnitsUsed",
    "OutputUnitsUsed",
    "ExecutionTimeMS",
    "IsUnmeasured",
    CASE
        WHEN "IsUnmeasured" = 1 THEN ''Unmeasured run: no token or unit counts recorded''
        ELSE ''Missing pricing: no price tier found for model at run time''
    END AS "UnpricedReason"
FROM ${flyway:defaultSchema}."vwAIUsageFacts"
WHERE "IsCompleted" = 1
  AND "IsPriced" = 0
  -- A parallel parent has no own cost BY DESIGN (the arms carry it), so it is not "unpriced".
  AND "IsParallelParent" = 0
  {% if start %}
  AND "RunAt" >= {{ start | sqlDate }}
  {% endif %}
  {% if end %}
  AND "RunAt" < {{ end | sqlDate }}
  {% endif %}
ORDER BY
    "RunAt" DESC
LIMIT {% if maxRows %}{{ maxRows | sqlNumber }}{% else %}500{% endif %}
' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[QuerySQL]
    WHERE
      [ID] = @ID_28b59a90308b
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateQuerySQL @ID = @ID_28b59a90308b,
  @QueryID = @QueryID_28b59a90308b,
  @SQLDialectID = @SQLDialectID_28b59a90308b,
  @SQL = @SQL_28b59a90308b
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_28b59a90308b,
  @QueryID = @QueryID_28b59a90308b,
  @SQLDialectID = @SQLDialectID_28b59a90308b,
  @SQL = @SQL_28b59a90308b
END;

