  @QueryID = @QueryID_cf2a4b819a30,
  @SQLDialectID = @SQLDialectID_cf2a4b819a30,
  @SQL = @SQL_cf2a4b819a30
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_cf2a4b819a30,
  @QueryID = @QueryID_cf2a4b819a30,
  @SQLDialectID = @SQLDialectID_cf2a4b819a30,
  @SQL = @SQL_cf2a4b819a30
