DECLARE @ID_95ee1923ff71 UNIQUEIDENTIFIER,
@QueryID_95ee1923ff71 UNIQUEIDENTIFIER,
@SQLDialectID_95ee1923ff71 UNIQUEIDENTIFIER,
@SQL_95ee1923ff71 NVARCHAR(MAX)
SET
  @ID_95ee1923ff71 = '6F698DC3-BD0A-43BA-A933-10E5ED9B6799'
SET
  @QueryID_95ee1923ff71 = 'C2162354-AB2F-4244-8659-C5A4E213E9FA'
SET
  @SQLDialectID_95ee1923ff71 = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_95ee1923ff71 = N'-- PostgreSQL variant: User Activity Summary
-- Mirrors user-activity-summary.sql. Differences:
--   * View and column names double-quoted, since PG folds unquoted names to lower case.
--   * The composed queries are the same; each resolves to its own PostgreSQL variant.
SELECT
    au."Name" AS "UserName",
    au."Email",
    au."Type" AS "UserType",
    COALESCE(rc."ChangeCount", 0) AS "RecentChanges",
    rc."LatestChange"
FROM
    {{query:"MJ/Demos/Active Users"}} au
    LEFT JOIN {{query:"MJ/Demos/Recent Entity Changes(lookbackDays=''30'')"}} rc
        ON rc."EntityName" IN (
            SELECT e."Name"
            FROM ${flyway:defaultSchema}."vwEntities" e
            WHERE e."ID" IN (
                SELECT DISTINCT rch."EntityID"
                FROM ${flyway:defaultSchema}."vwRecordChanges" rch
                WHERE rch."UserID" = au."ID"
            )
        )
ORDER BY
    COALESCE(rc."ChangeCount", 0) DESC,
    au."Name"
' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[QuerySQL]
    WHERE
      [ID] = @ID_95ee1923ff71
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateQuerySQL @ID = @ID_95ee1923ff71,
  @QueryID = @QueryID_95ee1923ff71,
  @SQLDialectID = @SQLDialectID_95ee1923ff71,
  @SQL = @SQL_95ee1923ff71
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_95ee1923ff71,
  @QueryID = @QueryID_95ee1923ff71,
  @SQLDialectID = @SQLDialectID_95ee1923ff71,
  @SQL = @SQL_95ee1923ff71
END;

