DECLARE @SQL_e9e5e62442dc NVARCHAR(MAX),
@ID_e9e5e62442dc UNIQUEIDENTIFIER
SET
  @SQL_e9e5e62442dc = N'-- PostgreSQL variant for External Change Detection - Detect Creations
SELECT
    ot.*, ot.{{ CreatedAtField | sqlIdentifier }} AS "__ecd_CreatedAt", ot.{{ UpdatedAtField | sqlIdentifier }} AS "__ecd_UpdatedAt"
FROM
    {{ SchemaName | sqlIdentifier }}.{{ BaseView | sqlIdentifier }} ot
LEFT JOIN
    ${flyway:defaultSchema}.vwRecordChanges rc
    ON
    ({{ PrimaryKeyJoin }} = rc.RecordID) AND
    rc.Type = ''Create'' AND
    rc.EntityID = {{ EntityID | sqlString }}
WHERE
    rc.RecordID IS NULL
ORDER BY
    {{ PrimaryKeyOrderBy }}
'
SET
  @ID_e9e5e62442dc = 'D85DE0AD-5B5B-4EF4-82BC-C634CE39E836' EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @SQL = @SQL_e9e5e62442dc,
  @ID = @ID_e9e5e62442dc;

-- Save MJ: Query SQLs (core SP call only)
DECLARE @SQL_7edab4b2ce7f NVARCHAR(MAX),
@ID_7edab4b2ce7f UNIQUEIDENTIFIER
SET
  @SQL_7edab4b2ce7f = N'-- PostgreSQL variant for External Change Detection - Detect Updates
SELECT
    ot.*, ot.{{ UpdatedAtField | sqlIdentifier }} AS "__ecd_UpdatedAt", rc.last_change_time AS "__ecd_LatestRecordChangeAt"
FROM
    {{ SchemaName | sqlIdentifier }}.{{ BaseView | sqlIdentifier }} ot
INNER JOIN (
    SELECT
        RecordID, MAX(ChangedAt) AS last_change_time
    FROM
        ${flyway:defaultSchema}.vwRecordChanges
    WHERE
        Type IN (''Update'', ''Create'') AND EntityID = {{ EntityID | sqlString }}
    GROUP BY
        RecordID
) rc ON {{ PrimaryKeyJoin }} = rc.RecordID
WHERE
    ot.{{ UpdatedAtField | sqlIdentifier }} > COALESCE(rc.last_change_time, CAST(''1900-01-01 00:00:00.000'' AS TIMESTAMPTZ))
ORDER BY
    {{ PrimaryKeyOrderBy }}
'
SET
  @ID_7edab4b2ce7f = '565C5AF3-5F59-4531-B21D-53EBC884EF5B' EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @SQL = @SQL_7edab4b2ce7f,
  @ID = @ID_7edab4b2ce7f;

-- Save MJ: Query SQLs (core SP call only)
DECLARE @SQL_c022e474bea9 NVARCHAR(MAX),
@ID_c022e474bea9 UNIQUEIDENTIFIER
SET
  @SQL_c022e474bea9 = N'-- PostgreSQL variant for External Change Detection - Detect Deletions
-- TECHNICAL DEBT: Joining on dynamically generated PrimaryKeyJoin (a concatenated string) prevents
-- the use of indexes on the organic table (ot). For massive tables, this will result in a table scan.
-- A future schema change to separate RecordID parts into native columns is recommended.
SELECT 
    rc.RecordID, MAX(rc.ChangedAt) AS "ChangedAt"
FROM 
    ${flyway:defaultSchema}.vwRecordChanges rc
LEFT JOIN 
    {{ SchemaName | sqlIdentifier }}.{{ BaseView | sqlIdentifier }} ot 
    ON 
    rc.RecordID = {{ PrimaryKeyJoin }}
WHERE 
    {{ PrimaryKeyIsNull }}
    AND 
        rc.EntityID = {{ EntityID | sqlString }} 
    AND 
        rc.Type <> ''Delete''
GROUP BY 
    rc.RecordID
HAVING 
    MAX(CASE WHEN rc.Type = ''Delete'' THEN 1 ELSE 0 END) = 0;
'
SET
  @ID_c022e474bea9 = 'F325DCBE-347F-4F59-9A8A-A18706803C8B' EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @SQL = @SQL_c022e474bea9,
  @ID = @ID_c022e474bea9;

