-- Save MJ: Query SQLs (core SP call only)
DECLARE @ID_03aec7614b76 UNIQUEIDENTIFIER,
@QueryID_03aec7614b76 UNIQUEIDENTIFIER,
@SQLDialectID_03aec7614b76 UNIQUEIDENTIFIER,
@SQL_03aec7614b76 NVARCHAR(MAX)
SET
  @ID_03aec7614b76 = '18717A30-0910-4E84-8FA7-BBA194E13AFF'
SET
  @QueryID_03aec7614b76 = 'EE272535-9D1D-4E4B-8613-1332CB564501'
SET
  @SQLDialectID_03aec7614b76 = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_03aec7614b76 = N'-- PostgreSQL variant: Get Conversation Artifacts Map — basic artifact info for a conversation, without
-- the full content.
-- Mirrors get-conversation-artifacts-map.sql. Differences:
--   * `[${flyway:defaultSchema}].[X]` → `${flyway:defaultSchema}."X"`; column names double-quoted, since PG folds unquoted names to lower case.
SELECT
    cda."ConversationDetailID",
    cda."Direction",
    av."ID" AS "ArtifactVersionID",
    av."VersionNumber",
    av."ArtifactID",
    a."Name" AS "ArtifactName",
    a."Type" AS "ArtifactType",
    a."Description" AS "ArtifactDescription"
FROM ${flyway:defaultSchema}."vwConversationDetailArtifacts" cda
INNER JOIN ${flyway:defaultSchema}."vwArtifactVersions" av ON cda."ArtifactVersionID" = av."ID"
INNER JOIN ${flyway:defaultSchema}."vwArtifacts" a ON av."ArtifactID" = a."ID"
INNER JOIN ${flyway:defaultSchema}."vwConversationDetails" cd ON cda."ConversationDetailID" = cd."ID"
WHERE cd."ConversationID" = {{ ConversationID | sqlString }}
  AND cda."Direction" = ''Output''
ORDER BY cda."__mj_CreatedAt", av."VersionNumber"
' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[QuerySQL]
    WHERE
      [ID] = @ID_03aec7614b76
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateQuerySQL @ID = @ID_03aec7614b76,
  @QueryID = @QueryID_03aec7614b76,
  @SQLDialectID = @SQLDialectID_03aec7614b76,
  @SQL = @SQL_03aec7614b76
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_03aec7614b76,
  @QueryID = @QueryID_03aec7614b76,
  @SQLDialectID = @SQLDialectID_03aec7614b76,
  @SQL = @SQL_03aec7614b76
END;

