-- Save MJ: Query SQLs (core SP call only)
DECLARE @ID_d6550b2719f8 UNIQUEIDENTIFIER,
@QueryID_d6550b2719f8 UNIQUEIDENTIFIER,
@SQLDialectID_d6550b2719f8 UNIQUEIDENTIFIER,
@SQL_d6550b2719f8 NVARCHAR(MAX)
SET
  @ID_d6550b2719f8 = 'B3FCE5D8-B973-4E6E-9D69-4BB8302BA219'
SET
  @QueryID_d6550b2719f8 = 'F3D2A1B8-9C4E-4E7A-BCDE-1234567ABCDE'
SET
  @SQLDialectID_d6550b2719f8 = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_d6550b2719f8 = N'-- PostgreSQL variant: aggregate stats over the same filter universe as ListConversationDetailFeedback.
-- Mirrors list-conversation-detail-feedback-stats.sql. Differences:
--   * `[${flyway:defaultSchema}].X` / `[User]` → `${flyway:defaultSchema}."X"` / `"User"`; column names double-quoted, since PG folds
--     unquoted names to lower case.
--   * `LIKE` → `ILIKE`: the search is case-insensitive, which SQL Server''s default collation gives
--     LIKE and PG''s LIKE does not.
SELECT
    COUNT(*)                                                                  AS "Total",
    AVG(CAST(cd."UserRating" AS FLOAT))                                       AS "AvgRating",
    SUM(CASE WHEN cd."UserRating" >= 8 THEN 1 ELSE 0 END)                     AS "PositiveCount",
    SUM(CASE WHEN cd."UserRating" <= 3 THEN 1 ELSE 0 END)                     AS "NegativeCount"
FROM ${flyway:defaultSchema}."ConversationDetail" cd
LEFT JOIN ${flyway:defaultSchema}."Conversation" c  ON c."ID"  = cd."ConversationID"
LEFT JOIN ${flyway:defaultSchema}."User"         cu ON cu."ID" = c."UserID"
LEFT JOIN ${flyway:defaultSchema}."AIAgent"      a  ON a."ID"  = cd."AgentID"
WHERE cd."UserRating" IS NOT NULL
    {% if StartDate %}
    AND cd."__mj_UpdatedAt" >= {{ StartDate | sqlString }}
    {% endif %}
    {% if EndDate %}
