-- Save MJ: Query SQLs (core SP call only)
DECLARE @ID_b32a74b8315a UNIQUEIDENTIFIER,
@QueryID_b32a74b8315a UNIQUEIDENTIFIER,
@SQLDialectID_b32a74b8315a UNIQUEIDENTIFIER,
@SQL_b32a74b8315a NVARCHAR(MAX)
SET
  @ID_b32a74b8315a = '468F5491-94EB-4003-A844-E7041BAFA527'
SET
  @QueryID_b32a74b8315a = 'FACEF5AC-C979-4944-B41F-2BD2A20BEAE7'
SET
  @SQLDialectID_b32a74b8315a = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_b32a74b8315a = N'-- PostgreSQL variant: List Conversation Detail Feedback — 1-10 ratings + free-form comments left on AI
-- messages. The parameters and rater attribution are documented in list-conversation-detail-feedback.sql.
-- Mirrors list-conversation-detail-feedback.sql. Differences:
--   * `[${flyway:defaultSchema}].X` / `[User]` → `${flyway:defaultSchema}."X"` / `"User"`; column names double-quoted, since PG folds
--     unquoted names to lower case.
--   * `LIKE` → `ILIKE`: the search is case-insensitive, which SQL Server''s default collation gives
--     LIKE and PG''s LIKE does not.
SELECT
    cd."ID"                AS "RatingID",
    cd."UserRating"        AS "Rating",
    cd."UserFeedback"      AS "Comments",
    cd."__mj_UpdatedAt"    AS "RatedAt",

    c."UserID"             AS "RaterUserID",
    cu."Name"              AS "RaterName",
    cu."Email"             AS "RaterEmail",

    cd."ID"                AS "ConversationDetailID",
    cd."ConversationID"    AS "ConversationID",
    cd."Message"           AS "MessageText",
    cd."Role"              AS "MessageRole",
    cd."__mj_CreatedAt"    AS "MessageCreatedAt",

    c."Name"               AS "ConversationName",

    cd."AgentID"           AS "AgentID",
    a."Name"               AS "AgentName"
FROM ${flyway:defaultSchema}."ConversationDetail" cd
LEFT JOIN ${flyway:defaultSchema}."Conversation" c  ON c."ID"  = cd."ConversationID"
LEFT JOIN ${flyway:defaultSchema}."User"         cu ON cu."ID" = c."UserID"
LEFT JOIN ${flyway:defaultSchema}."AIAgent"      a  ON a."ID"  = cd."AgentID"
WHERE cd."UserRating" IS NOT NULL
    {% if StartDate %}
    AND cd."__mj_UpdatedAt" >= {{ StartDate | sqlString }}
    {% endif %}
    {% if EndDate %}
    AND cd."__mj_UpdatedAt" <= {{ EndDate | sqlString }}
    {% endif %}
    {% if MinRating %}
    AND cd."UserRating" >= {{ MinRating }}
    {% endif %}
    {% if MaxRating %}
    AND cd."UserRating" <= {{ MaxRating }}
    {% endif %}
    {% if AgentID %}
    AND cd."AgentID" = {{ AgentID | sqlString }}
    {% endif %}
    {% if SearchText %}
    AND (
            cd."UserFeedback" ILIKE {{ SearchText | sqlLikeContains }}
         OR cd."Message"      ILIKE {{ SearchText | sqlLikeContains }}
         OR a."Name"          ILIKE {{ SearchText | sqlLikeContains }}
         OR cu."Name"         ILIKE {{ SearchText | sqlLikeContains }}
         OR cu."Email"        ILIKE {{ SearchText | sqlLikeContains }}
    )
    {% endif %}
ORDER BY cd."__mj_UpdatedAt" DESC
' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[QuerySQL]
    WHERE
      [ID] = @ID_b32a74b8315a
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateQuerySQL @ID = @ID_b32a74b8315a,
  @QueryID = @QueryID_b32a74b8315a,
  @SQLDialectID = @SQLDialectID_b32a74b8315a,
  @SQL = @SQL_b32a74b8315a
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_b32a74b8315a,
  @QueryID = @QueryID_b32a74b8315a,
  @SQLDialectID = @SQLDialectID_b32a74b8315a,
  @SQL = @SQL_b32a74b8315a
END;

