-- Save MJ: Query SQLs (core SP call only)
DECLARE @ID_74fee0d2f302 UNIQUEIDENTIFIER,
@QueryID_74fee0d2f302 UNIQUEIDENTIFIER,
@SQLDialectID_74fee0d2f302 UNIQUEIDENTIFIER,
@SQL_74fee0d2f302 NVARCHAR(MAX)
SET
  @ID_74fee0d2f302 = 'C10D9100-5343-4C40-89E3-85DB1D48CF13'
SET
  @QueryID_74fee0d2f302 = '4513AE64-76A5-432C-BA67-360C8A97753F'
SET
  @SQLDialectID_74fee0d2f302 = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[SQLDialect]
    WHERE
      LOWER([PlatformKey]) = LOWER(N'postgresql')
  )
SET
  @SQL_74fee0d2f302 = N'-- PostgreSQL variant: per-agent, per-rubric, per-criterion means for the two drift windows.
-- Submitted evaluations only. Self-checks are left out. Group rollups are left out.
-- Mirrors rubric-drift-period-means.sql. Differences:
--   * `[${flyway:defaultSchema}].[X]` / `[Column]` → `${flyway:defaultSchema}."X"` / `"Column"`, since PG folds unquoted names to lower case.
--   * `RubricEvaluationScore.IsComputed` is a boolean in PG, so it is compared with false rather than 0.
--   * `TRY_CONVERT(uniqueidentifier, SubjectRecordID)` has no PG equivalent; the run is matched by its ID
--     as text against the lower-cased subject record ID, so a subject that is not a UUID matches nothing,
--     as it does on SQL Server.
SELECT
    agent."Name" AS "AgentName",
    rubric."Name" AS "RubricName",
    criterion."Key" AS "CriterionKey",
    AVG(CASE
        WHEN evaluation."SubmittedAt" >= {{ currentStart | sqlDate }}
         AND evaluation."SubmittedAt" < {{ periodEnd | sqlDate }}
        THEN score."NormalizedScore"
    END) AS "CurrentMean",
    AVG(CASE
        WHEN evaluation."SubmittedAt" >= {{ previousStart | sqlDate }}
         AND evaluation."SubmittedAt" < {{ currentStart | sqlDate }}
        THEN score."NormalizedScore"
    END) AS "PreviousMean"
FROM ${flyway:defaultSchema}."RubricEvaluationScore" score
INNER JOIN ${flyway:defaultSchema}."RubricEvaluation" evaluation ON evaluation."ID" = score."EvaluationID"
INNER JOIN ${flyway:defaultSchema}."RubricVersion" version ON version."ID" = evaluation."RubricVersionID"
INNER JOIN ${flyway:defaultSchema}."Rubric" rubric ON rubric."ID" = version."RubricID"
INNER JOIN ${flyway:defaultSchema}."RubricCriterion" criterion ON criterion."ID" = score."CriterionID"
INNER JOIN ${flyway:defaultSchema}."AIAgentRun" run ON CAST(run."ID" AS TEXT) = LOWER(evaluation."SubjectRecordID")
INNER JOIN ${flyway:defaultSchema}."AIAgent" agent ON agent."ID" = run."AgentID"
WHERE evaluation."Status" = ''Submitted''
  AND evaluation."EvaluatorType" <> ''Self''
  AND score."IsComputed" = false
  AND score."NormalizedScore" IS NOT NULL
  AND evaluation."SubmittedAt" >= {{ previousStart | sqlDate }}
  AND evaluation."SubmittedAt" < {{ periodEnd | sqlDate }}
GROUP BY agent."Name", rubric."Name", criterion."Key"
' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[QuerySQL]
    WHERE
      [ID] = @ID_74fee0d2f302
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateQuerySQL @ID = @ID_74fee0d2f302,
  @QueryID = @QueryID_74fee0d2f302,
  @SQLDialectID = @SQLDialectID_74fee0d2f302,
  @SQL = @SQL_74fee0d2f302
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @ID = @ID_74fee0d2f302,
  @QueryID = @QueryID_74fee0d2f302,
  @SQLDialectID = @SQLDialectID_74fee0d2f302,
  @SQL = @SQL_74fee0d2f302
END;

