SET
  @Name_400e7d452a31 = N'Topic Explainer'
SET
  @Description_400e7d452a31 = N'Explains a technical concept, architecture, or workflow from first principles through progressive visual disclosure. Best when the audience needs clear cause-and-effect understanding within 60 to 120 seconds.'
SET
  @Category_400e7d452a31 = N'Explainer'
SET
  @Status_400e7d452a31 = N'Active'
