  @Description = @Description_400e7d452a31,
  @CompanyID = @CompanyID_400e7d452a31,
  @CompanyID_Clear = 1,
  @Category = @Category_400e7d452a31,
  @Status = @Status_400e7d452a31,
  @DefaultDurationSeconds = @DefaultDurationSeconds_400e7d452a31,
  @MinDurationSeconds = @MinDurationSeconds_400e7d452a31,
  @MaxDurationSeconds = @MaxDurationSeconds_400e7d452a31,
  @DefaultFormats = @DefaultFormats_400e7d452a31,
  @BeatTemplate = @BeatTemplate_400e7d452a31,
  @Pacing = @Pacing_400e7d452a31,
  @Guidance = @Guidance_400e7d452a31,
  @DefaultInteractionMode = @DefaultInteractionMode_400e7d452a31
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateVideoArchetype @ID = @ID_400e7d452a31,
